python3 -I - <<'PY'
import sqlite3, json, glob, os, collections
c=sqlite3.connect('file:data/guidebook.db?mode=ro',uri=True)
live={r[0] for r in c.execute("select ref_id from evidence_sources where superseded_by_ref_id is null")}
bykind=collections.defaultdict(set); ext=collections.defaultdict(set); nonnull=0
for m in glob.glob('retrieval-log/*/manifest.jsonl'):
    for line in open(m,encoding='utf-8'):
        try: r=json.loads(line)
        except Exception: continue
        if r.get('ref_id'): nonnull+=1
        ref=r.get('ref_id')
        if ref not in live: continue
        a=r.get('artefact') or ''
        p=a if os.path.exists(a) else os.path.join(os.path.dirname(m), os.path.basename(a))
        if r.get('derived_from'): bykind[r.get('derivation_kind')].add(ref)
        if os.path.exists(p): ext[os.path.splitext(p)[1].lower()].add(ref)
print('records with non-null ref_id', nonnull)
for k,v in bykind.items(): print(k, len(v))
tx=bykind['text-extraction']|bykind['extraction']
print('live sources with text-extraction or extraction record:', len(tx), '; text-extraction only:', len(bykind['text-extraction']))
print('page-render only (derived but no text kind):', len((bykind['page-render']|bykind['render']|bykind['pdf-bibliography'])-tx))
print('on-disk artefact extensions (sources):', {k:len(v) for k,v in ext.items()})
PY

